    if (logo === 'logo_lightning') return 'custom|circle|#ea580c|lightning|#facc15';
    if (logo === 'logo_crown') return 'custom|shield|#7c3aed|crown|#fbbf24';
    if (logo === 'logo_sword') return 'custom|hexagon|#334155|sword|#cbd5e1';
